declare namespace tools.file_system {
  type BashArg = {
    command: string;
    /**
     * Seconds the command may run: 120 by default, at most 300. A command that runs longer is stopped, and the result keeps the output it wrote so far with `timed_out` set. For longer work, use `tools.process.start` instead.
     * @minimum 1
     * @maximum 300
     */
    timeout_seconds?: number;
  };
  type BashReturned = {
    command: string;
    stdout: string;
    stderr: string;
    returncode: number;
    was_truncated: boolean;
    /**
     * Whether the command was stopped at its timeout; `stdout` and `stderr` hold the output written before it.
     */
    timed_out?: boolean;
  };
  /**
   * Run a shell command and capture stdout, stderr, and its return code.
   *
   * The call blocks until the command exits, and a command still running after `timeout_seconds` is stopped. Start long-running commands, such as servers and long builds, with `tools.process.start` and read their output with `tools.process.output`.
   */
  function bash(arg: BashArg): Promise<BashReturned>;
}
